import * as React from "react"
import { useEffect, useRef, useState } from "react"
import * as Framer from "framer"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

/**
 * FlowerTransition: a pixel-grid flower that plays full screen as a page
 * transition, then fades out to reveal the page (intro), or fades in over
 * the page and plays before navigating away (outro).
 *
 * The animation is baked from the reference video by tools/bake.py: every
 * grid cell of every key frame is stored as up to four concentric squares
 * (outer radius + palette entry). At runtime key frames are interpolated by
 * time and drawn with batched fillRect-style paths on a <canvas>.
 *
 * Self-contained: only React and "framer" are imported.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 * @framerIntrinsicWidth 480
 * @framerIntrinsicHeight 270
 */

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

export type Direction = "intro" | "outro"
export type RenderStyle = "fine" | "classic"

export interface FlowerSettings {
    /** Seconds the flower animation takes (the reference is time-scaled). */
    duration: number
    /**
     * Seconds for the page reveal at the end of the intro (the page grows in
     * through the cream), and for the pixel-block fade of link transitions.
     */
    fadeDuration: number
    /** Seconds for the cream to spread from the flower over the whole page. */
    fillDuration: number
    /** Block columns across the viewport for the pixel fade. */
    pixelColumns: number
    /**
     * "fine": a dense halftone grid sampled from a smooth reconstruction of
     * the flower. "classic": the reference's coarse cells with outlines.
     */
    renderStyle: RenderStyle
    /** Pixel columns across the viewport in landscape (fine style). */
    cellColumns: number
    /** Pixel columns across the viewport in portrait (fine style). */
    mobileColumns: number
    /** Largest dot as a fraction of the grid pitch (fine style). */
    dotSize: number
    background: string
    creamColor: string
    redColor: string
    yellowColor: string
    blueColor: string
}

export const DEFAULT_SETTINGS: FlowerSettings = {
    duration: 1.8,
    fadeDuration: 0.8,
    fillDuration: 0.5,
    pixelColumns: 24,
    renderStyle: "fine",
    cellColumns: 128,
    mobileColumns: 64,
    dotSize: 0.82,
    background: "#08080C",
    creamColor: "#E8E8D8",
    redColor: "#F80000",
    yellowColor: "#F8C048",
    blueColor: "#1F3FFF",
}

